const D = { energy:.62, scale:1, speed:1, bipolar:.4, turb:.5, hue:190, x:.5, y:.5, style:'ring', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const u = Math.min(width, height);
const style = P.style, sd = (P.seed | 0);
const fr = i => { const s = Math.sin(i * 127.1 + sd * 311.7) * 43758.5453; return s - Math.floor(s); };

const BW = Math.max(360, Math.min(560, Math.round(width / 3.0)));
const BH = Math.max(120, Math.round(BW * height / width));
if (!S.gfx || S.bw !== BW || S.bh !== BH) { S.gfx = createGraphics(BW, BH); S.gfx.pixelDensity(1); S.bw = BW; S.bh = BH; }
const g = S.gfx;

// seeded shell radii / widths / colors
if (S.pnSeed !== sd) { S.pnSeed = sd;
  S.axis = fr(1) * 3.14159;
  S.asym = 0.7 + fr(2) * 0.5;
  S.tphase = fr(3) * 6.2831;
}

const T = K.t * (0.4 + P.speed * 0.6);
const sc = 0.5 + P.scale * 0.55;                          // nebula radial scale
const expo = 0.55 + P.energy * 1.4;
const gain = 1 + K.swell * 0.14 + A.rms * 0.25;
const axis = S.axis + T * 0.02;                            // slow bipolar-axis rotation
const ca = Math.cos(axis), sa = Math.sin(axis);
// breathing shell radii (incommensurate, slow) — perpetual, non-strobe
const br1 = 1 + 0.05 * Math.sin(T * 0.11) + 0.03 * Math.sin(T * 0.047 + 1.3);
const br2 = 1 + 0.045 * Math.sin(T * 0.083 + 2.1);
const R1 = 0.15 * sc * br1, R2 = 0.30 * sc * br2, R3 = 0.46 * sc * br1, R4 = 0.66 * sc * br2;
const cxB = P.x * BW, cyB = P.y * BH;
const RB = Math.min(BW, BH) * 1.0;
const bip = P.bipolar, tb = P.turb;
const hb = P.hue;
const hue2rgb = (h, out, m) => { // simple HSB(h,90,100)->rgb *m
  const c = 1, x = 1 - Math.abs(((h / 60) % 2) - 1); let r, gg, b;
  if (h < 60) { r = c; gg = x; b = 0; } else if (h < 120) { r = x; gg = c; b = 0; }
  else if (h < 180) { r = 0; gg = c; b = x; } else if (h < 240) { r = 0; gg = x; b = c; }
  else if (h < 300) { r = x; gg = 0; b = c; } else { r = c; gg = 0; b = x; }
  out[0] += r * 255 * m; out[1] += gg * 255 * m; out[2] += b * 255 * m;
};
const acc = [0, 0, 0];

g.loadPixels(); const pix = g.pixels;
const contour = style === 'ink';
for (let j = 0; j < BH; j++) {
  const ny = (j - cyB) / RB;
  for (let i = 0; i < BW; i++) {
    const nx = (i - cxB) / RB;
    // rotate into nebula frame
    let ex = nx * ca + ny * sa, ey = -nx * sa + ny * ca;
    const r = Math.sqrt(ex * ex + ey * ey) + 1e-4;
    const th = Math.atan2(ey, ex);
    const o = 4 * (j * BW + i);
    if (r > 0.95) { pix[o] = 6; pix[o + 1] = 7; pix[o + 2] = 13; pix[o + 3] = 255; continue; }
    // angular turbulence (wispy gas)
    const turb = 0.72 + tb * (0.28 * Math.sin(th * 6 + S.tphase + T * 0.15) + 0.18 * Math.sin(th * 11 - T * 0.1) + 0.12 * Math.sin(th * 3 + r * 8));
    // bipolar lobe factor: emission enhanced along axis (cos^2), pinched at waist
    const lobe = 1 + bip * (2.2 * Math.pow(Math.cos(th), 4) - 0.5);
    acc[0] = 0; acc[1] = 0; acc[2] = 0;
    // nested ionization shells (inner hot/blue -> outer red)
    const s1 = Math.exp(-Math.pow((r - R1) / (0.10 * sc), 2));   // inner high-ion (blue-white)
    const s2 = Math.exp(-Math.pow((r - R2) / (0.075 * sc), 2));  // OIII teal
    const s3 = Math.exp(-Math.pow((r - R3) / (0.065 * sc), 2));  // main ring red/pink (H-alpha)
