    else if (style === 'xray') { const t = (R * 0.3 + G * 0.5 + B); R = t * 0.5; G = t * 0.8; B = t; }
    R *= I; G *= I; B *= I;
    pix[o] = R > 255 ? 255 : R; pix[o + 1] = G > 255 ? 255 : G; pix[o + 2] = B > 255 ? 255 : B; pix[o + 3] = 255;
  }
}
